"""A new chat's name, written by Gemini from its first question (owner, 30 Oct 2026: "there's no title generated by
gemini for each chat"): one small request beside the answer, under the person's own sign-in; a name the person gave the
chat always stays."""
from __future__ import annotations

import asyncio
import json
from pathlib import Path
from typing import Any

import httpx
import pytest
from fastapi.testclient import TestClient
from tests.helpers import CEO_QUESTION, HEADERS, ask, login, make_settings
from tests.unit.test_code_assist import FakeGoogle, make

from wizard_agent.prompting import clean_title
from wizard_agent.replay import ReplayRuntime
from wizard_api.app import create_app
from wizard_api.store import Store


@pytest.mark.parametrize(("said", "title"), [
    ("**Title:** Marketing return by market, Q3.", "Marketing return by market, Q3"),
    ('"Sell-in vs sell-out by model"\n\nAnything else?', "Sell-in vs sell-out by model"),
    ("# Switchers from Apple and Xiaomi", "Switchers from Apple and Xiaomi"),
    ("   \n  ", None),
])
def test_geminis_name_is_cleaned_to_one_short_line(said, title):
    assert clean_title(said) == title
    assert len(clean_title("word " * 60) or "") <= 80


def answering(text: str | None) -> tuple[FakeGoogle, list[dict[str, Any]], Any]:
    fake, asked = FakeGoogle([]), []

    def handler(request: httpx.Request) -> httpx.Response:
        if str(request.url).endswith(":generateContent"):
            asked.append(json.loads(request.content))
            if text is None:
                return httpx.Response(500, json={"error": {"message": "backend error"}})
            return httpx.Response(200, json={"response": {"candidates": [{"content": {"parts": [
                {"text": "Let me think about it", "thought": True}, {"text": text}]}}]}})
        return fake(request)
    return fake, asked, handler


def test_the_name_is_asked_of_flash_not_pro_under_the_persons_own_project(tmp_path: Path):
    # Shipped with Pro, the fallback, answering every name (owner, 30 Oct: Pro's quota was used up while Flash was at 20 %).
    fake, asked, handler = answering("Title: Best return on marketing investment by market")
    rt, request = make(tmp_path, fake, model="gemini-3.8-flash", fallback="gemini-3.1-pro-preview")  # the defaults
    rt.transport = httpx.MockTransport(handler)
    title = asyncio.run(rt.title(request.user_home, request.user_id, "run_1", CEO_QUESTION))
    assert title == "Best return on marketing investment by market"
    [body] = asked
    assert body["model"] == "gemini-3.8-flash" and body["project"] == "corp-gemini"
    assert CEO_QUESTION in body["request"]["contents"][0]["parts"][0]["text"]
    assert "tools" not in body["request"]  # a name, not an analysis: no tools offered


def test_no_name_when_gemini_cannot_say(tmp_path: Path):
    fake, _, handler = answering(None)
    rt, request = make(tmp_path, fake)
    rt.transport = httpx.MockTransport(handler)
    assert asyncio.run(rt.title(request.user_home, request.user_id, "run_1", CEO_QUESTION)) is None


def test_a_name_the_person_gave_the_chat_stays(tmp_path: Path):
    store = Store(tmp_path / "w.sqlite3")
    chat = store.create_conversation("u1")
    store.touch_conversation(chat, CEO_QUESTION[:80])
    assert store.retitle_conversation("u1", chat, CEO_QUESTION[:80], "Marketing return by market")
    assert store.conversation("u1", chat)["title"] == "Marketing return by market"
    renamed = store.create_conversation("u1")
    store.touch_conversation(renamed, CEO_QUESTION[:80])
    store.rename_conversation("u1", renamed, "My own name")
    assert not store.retitle_conversation("u1", renamed, CEO_QUESTION[:80], "Gemini's name")
    assert store.conversation("u1", renamed)["title"] == "My own name"
    assert not store.retitle_conversation("u2", chat, "Marketing return by market", "Someone else's")


class TitledReplay(ReplayRuntime):
    def __init__(self, *args: Any, **kwargs: Any):
        super().__init__(*args, **kwargs)
        self.named: list[str] = []

    async def title(self, user_home: Path, user_id: str, run_id: str, question: str) -> str | None:
        self.named.append(question)
        return "Marketing return by market"


def test_the_first_answer_names_the_chat_and_a_follow_up_does_not(tmp_path: Path):
    settings = make_settings(tmp_path)
    runtime = TitledReplay(settings.transcripts_dir, 0)
    with TestClient(create_app(settings, runtime=runtime)) as client:
        login(client, "u-ceo")
        first = ask(client, CEO_QUESTION)
        chats = client.get("/api/v1/conversations").json()["conversations"]
        assert [c["title"] for c in chats if c["id"] == first["conversation_id"]] == ["Marketing return by market"]
        client.patch(f"/api/v1/conversations/{first['conversation_id']}", json={"title": "Mine"}, headers=HEADERS)
        ask(client, CEO_QUESTION, first["conversation_id"])
        assert runtime.named == [CEO_QUESTION]  # asked once, for the chat's first question only
        chats = client.get("/api/v1/conversations").json()["conversations"]
        assert [c["title"] for c in chats if c["id"] == first["conversation_id"]] == ["Mine"]
